APP_NAME = "Crowbar"

def __find_main_crowbar_dialog():
    return True if common.find_object(CrowbarObjects.main_Dialog_Window) is not None else False

def __hhc_slider_value_check(targetValue: int) -> None:
    """Checks the given targetValue for the functions that move the Hand Held Controller sliders (Collimator, Gantry, ASU) to see if the mouse is about to move outside of the object bounds.

    :param targetValue: Integer Value to be checked to see if it exceeds 119 or is under 14.
    :type targetValue: int

    :raises ValueError: If param targetValue is great than 119 or less than 14 this ValueError is thrown. Reason being, this will put the cursor outside the limits of the object bounds.
    """
    if targetValue > 119 or targetValue < 14:
        raise ValueError("""Taget value is set to a value outside of the allowed range. Please select a value that is between 14 and 119.
                         To move the slider all the way to left use = 14 |
                         To move the slider all the way to right use = 119""")

def __uim_lat_long_slider_value_check(targetValue: int) -> None:
    """Checks the given targetValue for the functions that move the User Interface Module sliders (Lat, Long) to see if the mouse is about to move outside of the object bounds.

    :param targetValue: Integer Value to be checked to see if it exceeds 61 or is under 13.
    :type targetValue: int

    :raises ValueError: If param targetValue is great than 61 or less than 13 this ValueError is thrown. Reason being, this will put the cursor outside the limits of the object bounds.
    """
    if targetValue > 61 or targetValue < 13:
            raise ValueError("""Taget value is set to a value outside of the allowed range. Please select a value that is between 13 and 61.
                            To move the slider all the way to left use = 13 |
                            To move the slider all the way to right use = 61""")

def __uim_height_slider_value_check(targetValue: int) -> None:
    """Checks the given targetValue for the functions that move the User Interface Module Height slider to see if the mouse is about to move outside of the object bounds.

    :param targetValue: Integer Value to be checked to see if it exceeds 67 or is under 13.
    :type targetValue: int

    :raises ValueError: If param targetValue is great than 67 or less than 13 this ValueError is thrown. Reason being, this will put the cursor outside the limits of the object bounds.
    """
    if targetValue > 67 or targetValue < 13:
            raise ValueError("""Taget value is set to a value outside of the allowed range. Please select a value that is between 13 and 67.
                            To move the slider all the way to left use = 13 |
                            To move the slider all the way to right use = 67""")

@deco.set_separate_app_context(APP_NAME)
def toggle_view() -> None:
    """Toggles the expanded view of Crowbar by right clicking the top menu bar and selecting the "Toggle View" menu item from the context menu.
    """
    if __find_main_crowbar_dialog():
        common.right_click_object_with_xy_offset(CrowbarObjects.main_Dialog_Window, 250, 10)
        common.find_object(CrowbarObjects.main_ContextMenu)
        common.left_click_object(CrowbarObjects.contextMenu_Toggle_View_MenuItem)

@deco.set_separate_app_context(APP_NAME)
def move_main_dialog(xPosition: int, yPosition: int) -> None:
    """Moves the main Crowbar application dialog to a given X and Y position.
    """
    common.move_windows_object(CrowbarObjects.main_Dialog_Window, xPosition, yPosition)

@deco.set_separate_app_context(APP_NAME)
def is_expanded() -> bool:
    """Confirms that the Crowbar is in the expanded state and returns a True value if it is, and a False value if it isn't.

    :return: True if application is expanded. False if it isn't
    :rtype: bool
    """
    return True if common.find_object(CrowbarObjects.main_Dialog_Window).width > 580 else False #type:ignore

