@deco.set_separate_app_context(APP_NAME)
def move_collimator_slider(targetValue: int) -> None:
    """Moves the Collimator slider that is apart of the Hand Held Controller (HHC) section of the Crowbar interface to either the left or right depending on the given value.\n
    To move the slider all the way to the left pass in 14\n
    To move the slider all the way to the right pass in 119\n

    :param targetValue: This value represents the position the mouse will move to along the X axis of the slider object boundary after the mouse press
    :type targetValue: int
    """
    __hhc_slider_value_check(targetValue)
    if __find_main_crowbar_dialog():
        common.mouse_press_and_move_within_object_x_axis_start(CrowbarObjects.handHeldControllerInterface_Collimator_Slider, xValue = targetValue)

