@deco.set_separate_app_context(APP_NAME)
def move_uim_table_height_slider(sliderDirection: str= "down", sliderShiftValue: int = 4, dragDuration: int = 2) -> None:
    """Selects the "Height" (vertical) slider in the User Interface Module (UIM) section on Crowbar
    and move it up or down by a given value for a given duration.

    :param str sliderDirection: The direction to move the slider. Can be "up" or "down"
    :param int sliderShiftValue: The amount to shift the slider in pixels. Default is 4.
    :param int dragDuration: The duration of time (in seconds) to drag the slider
    """
    # Get the table "Height" slider object from the User Interface Module (UIM) section
    try:
        # Crowbar Height slider object id for version from TCS 4.1.0.0)
        slider_object = common.find_object(CrowbarObjects.userInterfaceModule_Height_Slider, 1000)
    except:
        # Try alternate slider object id (different Crowbar version for 3TCS?)
        slider_object = common.find_object({"id": 1111}, 1000)

    if slider_object is not None:
        # Move the Crowbar slider up or down
        mx = slider_object.width // 2                               #type: ignore
        my = slider_object.height // 2                              #type: ignore
        sq.mouseMove(slider_object, mx, my)                         #type: ignore
        sq.mousePress(slider_object)                                #type: ignore
        if sliderDirection == "down":
            sq.mouseMove(slider_object, mx, my + sliderShiftValue)  #type: ignore   # Move the slider down
        else:
            sq.mouseMove(slider_object, mx, my - sliderShiftValue)  #type: ignore   # Move the slider up
        sq.snooze(dragDuration)                                     #type: ignore
        sq.mouseRelease(slider_object)                              #type: ignore
        sq.snooze(1)                                                #type: ignore

@deco.set_separate_app_context(APP_NAME)
def move_uim_table_lat_slider(sliderDirection: str= "left", sliderShiftValue: int = 4, dragDuration: int = 2) -> None:
    """Selects the "Lat" (lateral) slider in the User Interface Module (UIM) section on Crowbar
    and move it left or right by a given value for a given duration.

    :param str sliderDirection: The direction to move the slider. Can be "left" or "right"
    :param int sliderShiftValue: The amount to shift the slider in pixels. Default is 4.
    :param int dragDuration: The duration of time (in seconds) to drag the slider
    """
    # Get the Crowbar Table "Lat" slider control object
    try:
        # Crowbar Height slider object id for version from TCS 4.1.0.0)
        slider_object = common.find_object(CrowbarObjects.userInterfaceModule_Lat_Slider, 1000)
    except:
        # Try alternate slider object id (different Crowbar version for 3TCS?)
        slider_object = common.find_object({"id": 1108}, 1000)

    if slider_object is not None:
        # Move the Crowbar slider to the left or right
        mx = slider_object.width // 2                               #type: ignore
        my = slider_object.height // 2                              #type: ignore
        sq.mouseMove(slider_object, mx, my)                         #type: ignore
        sq.mousePress(slider_object)                                #type: ignore
        if sliderDirection == "left":
            sq.mouseMove(slider_object, mx + sliderShiftValue, my)  #type: ignore # Move the slider to the left (decrease lateral)
        else:
            sq.mouseMove(slider_object, mx - sliderShiftValue, my)  #type: ignore # Move the slider to the right (increase lateral)
        sq.snooze(dragDuration)                                     #type: ignore
        sq.mouseRelease(slider_object)                              #type: ignore
        sq.snooze(1)                                                #type: ignore

